DROP DATABASE IF EXISTS feria_sevilla;
CREATE DATABASE feria_sevilla;
USE feria_sevilla;

CREATE TABLE zonas(
nombre VARCHAR(40) PRIMARY KEY,
fecha_origen date not null,
fecha_fin date,
descripcion LONGTEXT
);


CREATE TABLE calles(
id INT AUTO_INCREMENT PRIMARY KEY,
nombre VARCHAR(60) NOT NULL UNIQUE,
zona VARCHAR(30),
FOREIGN KEY (zona) REFERENCES zonas(nombre),
longitud DECIMAL(6,2) NOT NULL,
ancho DECIMAL(6,2) NOT NULL,
capacidad INT NOT NULL
);

CREATE TABLE tipos_caseta(
id INT PRIMARY KEY AUTO_INCREMENT,
nombre VARCHAR(30) NOT NULL UNIQUE,
acceso_publico BOOLEAN NOT NULL DEFAULT(TRUE),
requiere_invitacion BOOLEAN NOT NULL DEFAULT(FALSE),
CHECK (acceso_publico = FALSE OR requiere_invitacion = FALSE)
);


CREATE TABLE caseta(
id INT AUTO_INCREMENT PRIMARY KEY,
nombre VARCHAR(100) NOT NULL UNIQUE,
numero INT NOT NULL,
calle INT NOT NULL,
tipo INT NOT NULL,
descripcion LONGTEXT,
aforo INT NOT NULL,
tamaño DECIMAL(6,2) NOT NULL,
cocina BOOLEAN NOT NULL,
escenario BOOLEAN NOT NULL,
telefono VARCHAR(20),
UNIQUE(calle, numero),
FOREIGN KEY (calle) REFERENCES calles(id),
FOREIGN KEY (tipo) REFERENCES tipos_caseta(id)
);

CREATE TABLE personas(
dni VARCHAR(9) PRIMARY KEY,
nombre VARCHAR(80),
apellidos VARCHAR(120),
telefono VARCHAR(20),
email VARCHAR(120),
fecha_nacimiento DATE
);

CREATE TABLE socios_caseta(
persona VARCHAR(9),
caseta INT,
fecha_alta DATE NOT NULL,
cuota DECIMAL(8,2),
activo BOOLEAN DEFAULT TRUE,
PRIMARY KEY(persona, caseta),
FOREIGN KEY (persona) REFERENCES personas(dni),
FOREIGN KEY (caseta) REFERENCES caseta(id)
);

CREATE TABLE responsables(
persona VARCHAR(9),
caseta INT,
cargo VARCHAR(40) NOT NULL,
PRIMARY KEY(persona, caseta),
FOREIGN KEY (persona, caseta) REFERENCES socios_caseta(persona, caseta)
);

CREATE TABLE tipos_atraccion(
id INT AUTO_INCREMENT PRIMARY KEY,
nombre VARCHAR(40) NOT NULL UNIQUE,
descripcion LONGTEXT
);


CREATE TABLE atracciones(
id INT AUTO_INCREMENT PRIMARY KEY,
nombre VARCHAR(80) NOT NULL,
tipo INT NOT NULL,
zona VARCHAR(40) NOT NULL,
feriante VARCHAR(9),
altura_minima INT,
precio DECIMAL(5,2),
capacidad INT,
observaciones LONGTEXT,
estado ENUM('ABIERTA','CERRADA','REVISION') DEFAULT('ABIERTA') NOT NULL,
fecha_montaje DATE,
fecha_desmontaje DATE,
fecha_revision DATE,
edad_minima INT,
FOREIGN KEY (tipo) REFERENCES tipos_atraccion(id),
FOREIGN KEY (zona) REFERENCES zonas(nombre),
FOREIGN KEY (feriante) REFERENCES personas(dni)
);

CREATE TABLE eventos(
id INT AUTO_INCREMENT PRIMARY KEY,
caseta INT NOT NULL,
nombre VARCHAR(100) NOT NULL,
tipo ENUM('ACTUACION','CENA','CONCIERTO','BAILE', 'ALMUERZO', 'CENA SOCIOS', 'ALMUERZO SOCIOS'),
fecha DATETIME NOT NULL,
organizador VARCHAR(9),
descripcion LONGTEXT,
FOREIGN KEY (caseta) REFERENCES caseta(id),
FOREIGN KEY (organizador) REFERENCES personas(dni)
);

CREATE TABLE tickets(
id INT AUTO_INCREMENT PRIMARY KEY,
atraccion INT NOT NULL,
fecha DATETIME NOT NULL,
precio DECIMAL(5,2) NOT NULL,
FOREIGN KEY (atraccion) REFERENCES atracciones(id)
);





