INSERT INTO zonas VALUES
('REAL','1973-04-23',NULL,'El Real de la Feria es el núcleo principal del recinto ferial de Sevilla y constituye el espacio donde se concentran la mayor parte de las casetas, las calles y las actividades sociales que caracterizan la Feria de Abril. Durante unos días cada primavera este lugar se transforma en una ciudad efímera perfectamente organizada, con calles paralelas iluminadas por miles de bombillas y decoradas con farolillos de colores. Las casetas, que pueden pertenecer a asociaciones, familias, empresas o entidades públicas, funcionan como puntos de encuentro donde se celebran comidas, actuaciones musicales, bailes por sevillanas y reuniones sociales que se prolongan hasta altas horas de la madrugada. El recinto cuenta con infraestructuras temporales que suministran electricidad, agua, saneamiento y servicios logísticos a las más de mil casetas que se instalan cada año. A lo largo del día también es habitual ver el tradicional paseo de caballos, en el que carruajes y jinetes recorren las calles del Real vestidos con trajes típicos. El ambiente que se genera combina tradición, música, gastronomía y convivencia social, convirtiendo esta zona en el corazón cultural y festivo de la feria sevillana.'),
('CALLE INFIERNO','1973-04-23',NULL,'La zona conocida popularmente como Calle del Infierno es el área del recinto ferial dedicada a las atracciones, espectáculos y actividades de ocio. Se trata de un gran parque de diversiones temporal que se instala cada año junto al Real de la Feria y que reúne una gran variedad de atracciones mecánicas, juegos infantiles, puestos de comida, tómbolas y espectáculos itinerantes. El nombre tradicional de Calle del Infierno procede del intenso ruido producido por la música, los motores de las atracciones y el bullicio constante de los visitantes que recorren esta zona durante toda la jornada. Aquí pueden encontrarse desde norias gigantes y montañas rusas hasta coches de choque, carruseles, simuladores y numerosos puestos de juego donde se pueden conseguir premios. La zona ocupa decenas de miles de metros cuadrados y atrae especialmente a familias con niños y jóvenes que buscan una experiencia distinta dentro de la feria. Aunque su ambiente es muy diferente al de las casetas del Real, la Calle del Infierno forma parte inseparable de la tradición de la feria y se ha convertido en uno de los espacios más concurridos del recinto.'),
('APARCAMIENTOS','1973-04-23',NULL,'La zona de aparcamientos corresponde a los espacios habilitados alrededor del recinto ferial para facilitar el acceso de visitantes que se desplazan hasta la feria en vehículo privado o transporte colectivo. Durante los días de celebración se habilitan miles de plazas distribuidas en diferentes áreas cercanas al Real de la Feria, conectadas mediante itinerarios peatonales, lanzaderas de autobús y servicios especiales de transporte público. Estas zonas forman parte de un amplio dispositivo de movilidad diseñado por el Ayuntamiento de Sevilla para gestionar el gran volumen de visitantes que acuden cada año a la feria. Además de servir como estacionamiento, los aparcamientos permiten distribuir el flujo de personas hacia las diferentes entradas del recinto y ayudan a evitar la congestión en las zonas más próximas a las casetas y atracciones. En muchos casos también se habilitan espacios específicos para autobuses turísticos, taxis y servicios logísticos relacionados con el funcionamiento del evento, como transporte de suministros o acceso de vehículos de emergencia.');
